/**
 * Short-lived GitHub credentials minted from the host's Cursor account.
 *
 * The token stays in memory. `GH_TOKEN` is updated for child `gh` processes,
 * while Octokit callers use {@link getToken} so long-lived clients refresh
 * without being rebuilt.
 */
import { CursorBackendError } from "./backend-client.js";
const REFRESH_LEEWAY_MS = 5 * 60_000;
const REFRESH_RETRY_MS = 60_000;
const FAILURE_CACHE_TTL_MS = 60_000;
const MAX_RETRY_AFTER_MS = 60 * 60_000;
const MIN_TIMER_DELAY_MS = 1_000;
export class CursorGithubCredentialProvider {
    constructor(options) {
        this.started = false;
        this.stopped = false;
        this.client = options.client;
        this.repos = [...options.scope.repos];
        this.permissions = options.scope.permissions;
        this.logger = options.logger ?? (() => { });
        this.now = options.now ?? (() => Date.now());
    }
    async start() {
        if (this.stopped) {
            throw new Error("Cursor account GitHub credentials have been stopped.");
        }
        if (this.started) {
            return;
        }
        this.previousGhToken = process.env.GH_TOKEN;
        this.started = true;
        try {
            const token = await this.getToken();
            this.installGhToken(token);
            this.scheduleRefresh();
        }
        catch (error) {
            this.started = false;
            this.restoreGhToken();
            throw error;
        }
    }
    async getToken() {
        if (this.stopped) {
            throw new Error("Cursor account GitHub credentials have been stopped.");
        }
        const now = this.now();
        if (this.cached !== undefined && now >= this.cached.expiresAtMs) {
            // Expired leases must not be served; drop them so the next mint is clean.
            this.cached = undefined;
            this.restoreGhToken();
        }
        if (this.cached !== undefined && now < this.cached.refreshAtMs) {
            return this.cached.token;
        }
        if (this.failure !== undefined && now < this.failure.retryAtMs && this.cached === undefined) {
            throw new Error(this.failure.message);
        }
        if (this.refreshPromise === undefined) {
            this.refreshPromise = this.refresh().finally(() => {
                this.refreshPromise = undefined;
            });
        }
        return this.refreshPromise;
    }
    stop() {
        this.started = false;
        this.stopped = true;
        if (this.refreshTimer !== undefined) {
            clearTimeout(this.refreshTimer);
            this.refreshTimer = undefined;
        }
        this.cached = undefined;
        this.failure = undefined;
        this.restoreGhToken();
    }
    async refresh() {
        try {
            const result = await this.client.getGithubToken(this.repos, {
                permissions: this.permissions,
            });
            if (this.stopped) {
                throw new Error("Cursor account GitHub credentials have been stopped.");
            }
            const expiresAtMs = Date.parse(result.expiresAt);
            if (!Number.isFinite(expiresAtMs) || expiresAtMs <= this.now() + REFRESH_LEEWAY_MS) {
                throw new Error("Cursor backend returned an invalid GitHub credential expiry.");
            }
            this.failure = undefined;
            this.cached = {
                token: result.token,
                expiresAtMs,
                refreshAtMs: expiresAtMs - REFRESH_LEEWAY_MS,
            };
            if (this.started) {
                this.installGhToken(result.token);
                this.scheduleRefresh();
            }
            this.logger(`[bdk] GitHub auth: refreshed Cursor account credential for ${this.repos.length} repo(s)`);
            return result.token;
        }
        catch (error) {
            const message = error instanceof Error ? error.message : String(error);
            if (this.cached !== undefined && this.now() < this.cached.expiresAtMs) {
                this.logger(`[bdk] GitHub auth: Cursor account credential refresh failed; using the current lease: ${message}`);
                this.cached.refreshAtMs = Math.min(this.cached.expiresAtMs, this.now() + REFRESH_RETRY_MS);
                if (this.started) {
                    this.scheduleRetry();
                }
                return this.cached.token;
            }
            // Hard failure with no usable lease: evict any stale cache and back off.
            this.cached = undefined;
            this.restoreGhToken();
            this.failure = {
                message,
                retryAtMs: this.now() + failureBackoffMs(error),
            };
            if (this.started) {
                this.scheduleRetry();
            }
            throw error instanceof Error ? error : new Error(message);
        }
    }
    scheduleRefresh() {
        if (!this.started || this.cached === undefined) {
            return;
        }
        this.replaceTimer(Math.max(MIN_TIMER_DELAY_MS, this.cached.refreshAtMs - this.now()));
    }
    scheduleRetry() {
        if (!this.started) {
            return;
        }
        const delayMs = this.failure !== undefined
            ? Math.max(MIN_TIMER_DELAY_MS, this.failure.retryAtMs - this.now())
            : REFRESH_RETRY_MS;
        this.replaceTimer(delayMs);
    }
    replaceTimer(delayMs) {
        if (this.refreshTimer !== undefined) {
            clearTimeout(this.refreshTimer);
        }
        this.refreshTimer = setTimeout(() => {
            void this.getToken().catch((error) => {
                this.logger(`[bdk] GitHub auth: Cursor account credential refresh failed: ${error instanceof Error ? error.message : String(error)}`);
                this.scheduleRetry();
            });
        }, delayMs);
        this.refreshTimer.unref?.();
    }
    installGhToken(token) {
        process.env.GH_TOKEN = token;
        this.installedGhToken = token;
    }
    restoreGhToken() {
        if (this.installedGhToken !== undefined && process.env.GH_TOKEN === this.installedGhToken) {
            if (this.previousGhToken === undefined) {
                delete process.env.GH_TOKEN;
            }
            else {
                process.env.GH_TOKEN = this.previousGhToken;
            }
        }
        this.installedGhToken = undefined;
    }
}
function failureBackoffMs(error) {
    if (error instanceof CursorBackendError && error.retryAfterMs !== undefined) {
        return Math.min(Math.max(error.retryAfterMs, FAILURE_CACHE_TTL_MS), MAX_RETRY_AFTER_MS);
    }
    return FAILURE_CACHE_TTL_MS;
}
